import{_ as a,o,c as t,a0 as n}from"./chunks/framework.CWg_RwV0.js";const m=JSON.parse('{"title":"Tech Notes","description":"","frontmatter":{},"headers":[],"relativePath":"tech-notes.md","filePath":"tech-notes.md"}'),s={name:"tech-notes.md"};function r(l,e,i,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="tech-notes" tabindex="-1">Tech Notes <a class="header-anchor" href="#tech-notes" aria-label="Permalink to &quot;Tech Notes&quot;">​</a></h1><p>Tech Notes explains the engineering behind nP&#39;s models and calculations. Each note develops a concept, follows the relevant equations, and connects them to a concrete nP result.</p><h2 id="rf-networks-and-device-models" tabindex="-1">RF networks and device models <a class="header-anchor" href="#rf-networks-and-device-models" aria-label="Permalink to &quot;RF networks and device models&quot;">​</a></h2><p>An n-port describes a circuit through the waves at its external ports. The RF notes develop S-parameters from incident and outgoing waves, explain how component models become connected networks, and follow the signals measured by a vector network analyzer.</p><p>Device notes connect internal physics to those external models. The NPN note follows the Gummel–Poon model through its DC operating point, stored charge, small-signal RF response, noise and weak nonlinear behavior.</p><h2 id="sampled-signals" tabindex="-1">Sampled signals <a class="header-anchor" href="#sampled-signals" aria-label="Permalink to &quot;Sampled signals&quot;">​</a></h2><p>The signal notes explain sampling, quantization, waveform generation, Fourier transforms and modulation. They track how a voltage waveform becomes samples, how those samples map to frequency bins, and how a modulated signal is prepared for an RF network.</p><p>Choose a note from the left sidebar. The previous and next controls follow the same reading order.</p>',8)])])}const u=a(s,[["render",r]]);export{m as __pageData,u as default};
